add(nr=512, id="10472213250314", orig_titel="Viktväska TUNTURI Strengthbag 5kg, orange",
 fakta="Viktväska TUNTURI Strengthbag 5kg, orange. Fördelar med Tunturi viktväska: Stark fitnessväska med olika handtag för att träna armar, ben, axlar och rygg. Slitstarkt material: kan användas inomhus och utomhus Kombination av kettlebell, medicinboll och skivstång. Lätt att justera vikten genom att ta bort sandpåsarna. \"Må bättre varje dag\" - det är Tunturimottot. Våra rötter går tillbaka till Finland, där två bröder startade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödjande appar. Det är ett sortiment som ständigt utökas och växer, med kvalitetsprodukter och bra garantier. Översikt över specifikationer: Längd. Diameter: 23 cm Vikt: 5 kg 23,5 kg: 23,5 cm, 23,5 tum. Färg: Orange | Grå Material: Bizonyl | Sandfyllning Finns i olika vikter (färger). Märke Tunturi, typ Cykelväskor, taggar Cykelväska, Cykelväskor, varianter Default Title (SKU 14TUSCL362) och yellow (SKU 14TUSCL362)",
 titel="Viktväska Tunturi Strengthbag 5 kg, orange",
 seo_title="Viktväska Tunturi Strengthbag 5 kg, orange",
 meta="Tunturi Strengthbag är en viktväska på 5 kg med diameter 23 cm och olika handtag. Vikten justeras genom att ta bort sandpåsarna. Orange.",
 intro="Tunturi Strengthbag är en viktväska på 5 kg med olika handtag och sandpåsar. Vikten justeras genom att ta bort sandpåsarna.",
 passar=["Dig som vill träna armar, ben, axlar och rygg med olika handtag","Dig som vill ha en kombination av kettlebell, medicinboll och skivstång","Träning inomhus och utomhus"],
 spec=["Vikt: 5 kg","Diameter: 23 cm","Färg: orange (finns även grå)","Fyllning: sand, vikten justeras genom att ta bort sandpåsarna","Finns i olika vikter (färger)"],
 faq=[("Kan jag ändra vikten?","Ja, vikten justeras genom att ta bort sandpåsarna.")], marke=None,
 motivering="Fakta ur källan. Utelämnat: \"stark\" och \"slitstarkt\" (värderande), Tunturis motto och märkestext (\"frisk och vältränad kropp\", landsangivelse och historia), material \"Bizonyl\" och raden \"23,5 kg: 23,5 cm, 23,5 tum\" (se att bekräfta).",
 att_bekrafta=["Produkttypen är \"Cykelväskor\" och taggarna är Cykelväska/Cykelväskor, men produkten är en viktväska. Fel typ/taggar i butiken.","Materialet \"Bizonyl\" är oklart (maskinöversättning?). Utelämnat. Bekräfta.","Raden \"23,5 kg: 23,5 cm, 23,5 tum.\" är obegriplig och \"Längd.\" är tom. Utelämnade.","Två varianter med samma SKU (14TUSCL362): Default Title och \"yellow\". Titeln säger orange, specen \"Orange | Grå\" och varianten \"yellow\". Bekräfta färger.","Hur många sandpåsar som ingår och vad de väger saknas i källan."])

add(nr=513, id="10472259191050", orig_titel="Massagepistol Tunturi MG50 Massagepistol",
 fakta="Massagepistol Tunturi MG50 Massagepistol. Tunturi MG50 massagepistol är ett utmärkt verktyg för att värma upp muskler före eller efter ett träningspass för att minska smärta och spänningar i kroppen. Denna professionella massör stimulerar cirkulationen och hjälper till att påskynda muskelåterhämtningen. Men massagepistolen är också en idealisk partner för allmän avslappning och för att minska stress i kropp och sinne. Fördelar: Minskar stress, smärta och muskelspänningar. Stimulerar blodcirkulationen Lindrar stress och spänningar, lindrar stress och spänningar, minskar stress och spänningar 4 massagelägen för att massera olika kroppsdelar och olika muskelgrupper. 3 förinställda program och manuellt läge Olika användningsområden Massagepistolen har tjugo olika hastighetsinställningar från 1200 till maximalt 3300 varv/min. Den kan användas för alla typer av massage, från ytlig massage till massage av djupare muskler. Fyra massagelägen ingår: boll, gaffel, boll och platt huvud. Dessa fyra massagelägen kan användas för att massera alla olika kroppsdelar och muskelgrupper. Enkel att använda LED-pekskärmen på enheten gör det enkelt att välja hastighet och visar även återstående batterikraft. Det kraftfulla litiumjonbatteriet har en batteritid på fem till elva timmar, beroende på vilken massagehastighet som används. Enheten har tre förinställda program och ett manuellt läge. Enheten är lätt och kan bäras i en bekväm bärväska. \"Må bättre varje dag\" - det är Tuntur's motto. Våra rötter går tillbaka till Finland, där två bröder grundade en cykelbutik 1922. Nu, över 100 år senare, är vi ett holländskt företag och ett globalt varumärke. Vi stöder dig på din resa mot en frisk och vältränad kropp, ett balanserat sinne och ett lyckligt liv. Vi gör detta med ett brett utbud av konditions- och styrketräningsutrustning, tillbehör och stödjande appar. Sortimentet utökas och förbättras ständigt och erbjuder kvalitetsprodukter och utmärkta garantier. Märke Tunturi, typ Massage, varianter Default Title, SKU 14TUSYO059",
 titel="Massagepistol Tunturi MG50, 4 massagelägen, LED-pekskärm",
 seo_title="Massagepistol Tunturi MG50, 4 massagelägen",
 meta="Tunturi MG50 är en massagepistol med tjugo hastighetsinställningar från 1200 till 3300 varv/min, LED-pekskärm, litiumjonbatteri och bärväska.",
 intro="Tunturi MG50 är en massagepistol med tjugo hastighetsinställningar från 1200 till 3300 varv/min och LED-pekskärm. Den har 4 massagelägen, 3 förinställda program och manuellt läge.",
 passar=["Dig som vill välja bland tjugo hastighetsinställningar","Dig som vill ha förinställda program och ett manuellt läge","Dig som vill kunna bära massagepistolen i en bärväska"],
 spec=["Hastighetsinställningar: tjugo, från 1200 till maximalt 3300 varv/min","Massagelägen: 4","Program: 3 förinställda och manuellt läge","Skärm: LED-pekskärm, visar hastighet och återstående batterikraft","Batteri: litiumjon, batteritid fem till elva timmar beroende på massagehastighet","Bärväska ingår"],
 faq=[("Hur länge räcker batteriet?","Enligt källan fem till elva timmar, beroende på vilken massagehastighet som används.")], marke=None,
 motivering="Fakta ur källan. Utelämnat: alla hälso- och effektpåståenden (minska smärta, spänningar och stress, stimulera cirkulation, påskynda återhämtning, avslappning), \"utmärkt\", \"idealisk\", \"professionell\", \"kraftfullt\", Tunturis motto och märkestext. Tal skrivs som i källan (ord där källan använder ord).",
 att_bekrafta=["Listan över massagehuvuden är trasig (\"boll, gaffel, boll och platt huvud\" med boll två gånger). Huvudena namnges därför inte.","Fördelslistan upprepar samma rad tre gånger (maskinöversättning).","Titeln upprepar \"Massagepistol\" (\"Massagepistol Tunturi MG50 Massagepistol\"). Titeln i utkastet har inte dubbletten.","Vikt, mått och laddningssätt saknas i källan. Litiumjonbatteri kan kräva säkerhetstext."])

